describe('Date Picker Keyboard Operability', () => {
  beforeEach(() => {
    cy.visit('/date-picker');
  });

  it('should navigate through date picker using arrow keys and select a date', () => {
    // Open date picker
    cy.get('[data-testid="date-picker-input"]').click();

    // Verify date picker is visible
    cy.get('[data-testid="date-picker-container"]').should('be.visible');

    // Navigate to previous month using left arrow
    cy.get('[data-testid="prev-month-button"]').click();
    cy.get('[data-testid="date-picker-container"]').should('be.visible');
    cy.get('[data-testid="date-picker-input"]').should('contain', '12');

    // Navigate to next month using right arrow
    cy.get('[data-testid="next-month-button"]').click();
    cy.get('[data-testid="date-picker-container"]').should('be.visible');
    cy.get('[data-testid="date-picker-input"]').should('contain', '01');

    // Navigate to current day using down arrow
    cy.get('[data-testid="down-arrow-button"]').click();
    cy.get('[data-testid="date-picker-input"]').should('contain', '01');

    // Navigate to next day using down arrow
    cy.get('[data-testid="down-arrow-button"]').click();
    cy.get('[data-testid="date-picker-input"]').should('contain', '02');

    // Select a specific date using tab and enter
    cy.get('[data-testid="date-picker-input"]').should('be.visible');
    cy.get('[data-testid="date-picker-input"]').type('15');
    cy.get('[data-testid="date-picker-input"]').type('{enter}');

    // Verify date is selected
    cy.get('[data-testid="selected-date-label"]').should('contain', '15');

    // Verify date picker closes
    cy.get('[data-testid="date-picker-container"]').should('not.exist');
  });

  it('should handle edge case when navigating to last day of month', () => {
    // Open date picker
    cy.get('[data-testid="date-picker-input"]').click();
    cy.get('[data-testid="date-picker-container"]').should('be.visible');

    // Navigate to last day of previous month
    cy.get('[data-testid="prev-month-button"]').click();
    cy.get('[data-testid="date-picker-input"]').should('contain', '31');

    // Navigate to last day of current month
    cy.get('[data-testid="prev-month-button"]').click();
    cy.get('[data-testid="date-picker-input"]').should('contain', '31');

    // Navigate to last day of next month
    cy.get('[data-testid="prev-month-button"]').click();
    cy.get('[data-testid="date-picker-input"]').should('contain', '31');

    // Verify date picker does not allow navigation beyond last day
    cy.get('[data-testid="prev-month-button"]').click();
    cy.get('[data-testid="date-picker-input"]').should('contain', '31');

    // Verify date picker remains open
    cy.get('[data-testid="date-picker-container"]').should('be.visible');
  });
});
